def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest().upper()
def fail(msg): print('APPLY_FIX331028_FAILED: '+msg); return 1
def main():
    if len(sys.argv)!=2:return fail('usage: apply-fix331028.py <extension-root>')
    root=Path(sys.argv[1]).resolve()
    if not root.is_dir():return fail('root missing: '+str(root))
    try:m=json.loads((root/'manifest.json').read_text(encoding='utf-8-sig'))
    except Exception as e:return fail('manifest unreadable: '+str(e))
    actual={rel:sha(root/rel) for rel in EXPECTED if (root/rel).is_file()}
    if m.get('version_name')==NEW_VERSION and m.get('version')==NEW_MANIFEST_VERSION and all(actual.get(k)==OUTPUT_EXPECTED[k] for k in OUTPUT_EXPECTED):
        print('APPLY_FIX331028_ALREADY_OK');return 0
    mism=[f'{k}={actual.get(k,"MISSING")} expected={v}' for k,v in EXPECTED.items() if actual.get(k)!=v]
    if m.get('version_name')!=OLD_VERSION or m.get('version')!=OLD_MANIFEST_VERSION:mism.append(f'manifest version={m.get("version")} version_name={m.get("version_name")}')
    if mism:return fail('input hash mismatch: '+', '.join(mism))
    decoded={}
    try:
        for rel,data in PAYLOADS.items():
            b=zlib.decompress(base64.b85decode(data.encode('ascii')))
            if hashlib.sha256(b).hexdigest().upper()!=OUTPUT_EXPECTED[rel]:raise RuntimeError('payload hash mismatch: '+rel)
            decoded[rel]=b
    except Exception as e:return fail(str(e))
    temps=[]
    try:
        for rel,b in decoded.items():
            dest=root/rel;dest.parent.mkdir(parents=True,exist_ok=True);fd,tmp=tempfile.mkstemp(prefix=dest.name+'.331028.',dir=str(dest.parent));os.close(fd);tp=Path(tmp);tp.write_bytes(b);temps.append((tp,dest))
        for tp,dest in temps:os.replace(tp,dest)
    except Exception as e:
        for tp,_ in temps:
            try:tp.unlink(missing_ok=True)
            except Exception:pass
        return fail('write failed: '+str(e))
    bad=[f'{rel}={sha(root/rel)} expected={h}' for rel,h in OUTPUT_EXPECTED.items() if sha(root/rel)!=h]
    if bad:return fail('output hash mismatch: '+', '.join(bad))
    print('APPLY_FIX331028_PASS');return 0
if __name__=='__main__':raise SystemExit(main())
